def _canonical_sha256(core):
    data = json.dumps(
        core,
        ensure_ascii=False,
        sort_keys=True,
        separators=(",", ":"),
        allow_nan=False,
    ).encode("utf-8")
    return hashlib.sha256(data).hexdigest()


def _attention_names(components):
    names = []
    for name, result in components.items():
        if not isinstance(result, dict):
            raise ValueError("component result must be a JSON object")
        try:
            if result.get("blocked"):
                names.append(name)
                continue
            if result.get("feasible") is False or result.get("compatible") is False:
                names.append(name)
                continue
            if result.get("deny", 0) > 0:
                names.append(name)
                continue
            if result.get("score_total", 0) >= 20:
                names.append(name)
        except TypeError:
            # A malformed value (for example a string score) should fail rather
            # than silently skipping the component.
            raise
    return sorted(names)


def build_report():
    core = json.loads(CORE_PATH.read_text(encoding="utf-8"))
    components = core.get("components")
    if not isinstance(components, dict):
        raise ValueError("core_manifest.json must contain a components object")

    report = {
        "title": "搜索索引重建",
        "component_count": len(components),
        "sha256": _canonical_sha256(core),
        "attention": _attention_names(components),
    }

    OUT_PATH.parent.mkdir(parents=True, exist_ok=True)
    OUT_PATH.write_text(
        json.dumps(report, ensure_ascii=False, sort_keys=True, indent=2, allow_nan=False)
        + "\n",
        encoding="utf-8",
    )
    return report


